      ]
    },
    {
      "title": "[5] SASRec reference model and sequence construction",
      "link": "https://github.com/kang205/SASRec",
      "contributions": [
        "The reference model.py and util.py document learned absolute positional embeddings, truncated left-padded sequences, and final-slot scoring.",
        "Explain why compact deletion moves earlier surviving occurrences and why truncation must precede perturbation."
      ],
      "limitations": [
        "The actual RecHarness model and attention masks must be checked before implementing position-preserving removal; reference behavior alone cannot certify the adapter."
      ]
    },
    {
      "title": "[6] Recommendation data-leakage study",
      "link": "https://arxiv.org/abs/2010.11060",
      "contributions": [
        "The supplied search summary identifies temporal leakage risks, including globally future interactions exposed through per-user chronological splitting.",
        "Motivates fresh auxiliary fitting and explicit timestamp boundaries."
      ],
      "limitations": [
        "Does not make inference-only deletion a holdout or validate this proposed diagnostic."
      ]
    },
    {
      "title": "[7] Sequential recommendation splitting study",
      "link": "https://arxiv.org/abs/2507.16289",
      "contributions": [
        "The supplied summary motivates distinguishing per-user chronology from globally future prediction.",
        "Supports declaring what information is available when constructing auxiliary evaluation targets."
      ],
      "limitations": [
        "The suggested fresh-fit diagnostic construction is a methodological proposal here, not an established result for this benchmark."
      ]
    },
    {
      "title": "[8] Cawley and Talbot (2010): On Over-fitting in Model Selection and Subsequent Selection Bias in Performance Evaluation",
      "link": "https://www.jmlr.org/beta/papers/v11/cawley10a.html",
      "contributions": [
        "Explains model-selection overfitting and bias from optimizing noisy evaluation estimates.",
        "Motivates predeclared trial limits, complete trial records, and freezing diagnostic prediction rules before transfer evaluation."
      ],
      "limitations": [
        "Fixed seeds and bootstrap intervals do not eliminate adaptive search bias or supply an independent evaluation set."
      ]
    },
    {
      "title": "[9] Krichene and Rendle: On Sampled Metrics for Item Recommendation",
      "link": "https://research.google/pubs/on-sampled-metrics-for-item-recommendation/",
      "contributions": [
        "Shows that sampled recommendation metrics can disagree with full-catalog model rankings.",
        "Supports preserving the pinned evaluator and reporting full-catalog diagnostics as a separate protocol."
      ],
      "limitations": [
        "Does not justify changing the host's candidate sampling or replacing its HR@10 selection metric."
      ]
    }
  ]
